declare module '*.png' {
  const value: string
  export default value
}

declare module '*.jpg' {
  const value: string
  export default value
}

declare module '*.svg' {
  const value: string
  export default value
}

// If you use ?asset suffix in Vite
declare module '*?asset' {
  const value: string
  export default value
}
